catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
   if (isLoading || newValue == '') {
      return;
   }
   g_form.clearValue('key_version');
   g_form.clearOptions('key_version');
   g_form.setMandatory('key_version', false);
   g_form.setDisplay('key_version', false);
   var CA = g_form.getValue('certificate_authority');
   var bit_length =  g_form.getValue('bit_length');
   var key_type = g_form.getValue('key_type');
   var key_versions = ["128s-simple","128s-robust", "128f-simple", "128f-robust","192s-simple","192s-robust","192f-simple","192f-robust","256s-simple","256s-robust","256f-simple","256f-robust"]

   if (CA === 'AppViewX PKIaaS Native' && key_type === 'SPHINCSPLUS'){
	var half_bit_length = (parseInt(bit_length) / 2).toString();
	var filtered_key_versions = key_versions.filter(function(version) {
    return version.startsWith(half_bit_length);
    });
	g_form.setDisplay('key_version', true);
	g_form.setMandatory('key_version', true);
	g_form.addOption('key_version', '', 'Select');
	for (var key_version = 0; key_version < filtered_key_versions.length; key_version++) {
		g_form.addOption('key_version', filtered_key_versions[key_version], filtered_key_versions[key_version]);
		}
   } 
}
